// Takes the "Generated by Claude Code" footer off the end of a description or comment:
//
//     node .github/scripts/tidy-footers.mjs body.md tidy.md
//
// writes tidy.md only when there was one. Used by tidy-footers.yml; tested by
// tidy-footers.test.mjs.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

// Only at the very end: `$` without the m flag is the end of the text, not of a line.
const FOOTER = /(?:\s*\n-{3,}[ \t]*)?\s*(?:🤖[ \t]*)?_?Generated (?:by|with) \[Claude Code\]\([^)]*\)_?\s*$/u;

/** The text without the footer, or null when it has none. */
export function withoutFooter(body) {
  const tidy = body.replace(FOOTER, "");
  return tidy === body ? null : `${tidy.replace(/\s+$/, "")}\n`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const [from, to] = process.argv.slice(2);
  const tidy = withoutFooter(readFileSync(from, "utf8"));
  if (tidy !== null) writeFileSync(to, tidy);
}
